184 | class ShellContentRendererUrlLoaderThrottleProvider
185 |     : public blink::URLLoaderThrottleProvider {
186 |  public:
187 |   ShellContentRendererUrlLoaderThrottleProvider()
188 |       : main_thread_task_runner_(
189 |             content::RenderThread::IsMainThread()
190 |                 ? base::SequencedTaskRunner::GetCurrentDefault()
191 |                 : nullptr) {}
192 | 
193 |   // This constructor works in conjunction with Clone().
194 |   ShellContentRendererUrlLoaderThrottleProvider(
195 |       const scoped_refptr<base::SequencedTaskRunner>& main_thread_task_runner,
196 |       base::PassKey<ShellContentRendererUrlLoaderThrottleProvider>)
197 |       : main_thread_task_runner_(std::move(main_thread_task_runner)) {}
198 | 
199 |   std::unique_ptr<URLLoaderThrottleProvider> Clone() override {
200 |     return std::make_unique<ShellContentRendererUrlLoaderThrottleProvider>(
201 |         main_thread_task_runner_,
202 |         base::PassKey<ShellContentRendererUrlLoaderThrottleProvider>());
203 |   }
204 | 
205 |   std::vector<std::unique_ptr<blink::URLLoaderThrottle>> CreateThrottles(
206 |       base::optional_ref<const blink::LocalFrameToken> local_frame_token,
207 |       const network::ResourceRequest& request) override {
208 |     std::vector<std::unique_ptr<blink::URLLoaderThrottle>> throttles;
209 |     if (local_frame_token.has_value()) {
210 |       auto throttle =
211 |           content::MaybeCreateIdentityUrlLoaderThrottle(base::BindRepeating(
212 |               [](const blink::LocalFrameToken& token,
213 |                  const scoped_refptr<base::SequencedTaskRunner>
214 |                      main_thread_task_runner,
215 |                  network::mojom::RequestDestination destination,
216 |                  const std::optional<url::Origin>& initiator,
217 |                  const url::Origin& idp_origin,
218 |                  blink::mojom::IdpSigninStatus status) {
219 |                 if (content::RenderThread::IsMainThread()) {
220 |                   blink::SetIdpSigninStatus(token, idp_origin, status);
221 |                   return;
222 |                 }
223 |                 if (main_thread_task_runner) {
224 |                   main_thread_task_runner->PostTask(
225 |                       FROM_HERE, base::BindOnce(&blink::SetIdpSigninStatus,
226 |                                                 token, idp_origin, status));
227 |                 }
228 |               },
229 |               local_frame_token.value(), main_thread_task_runner_));
230 |       if (throttle)
231 |         throttles.push_back(std::move(throttle));
232 |     }
233 | 
234 |     return throttles;
235 |   }
236 | 
237 |   void SetOnline(bool is_online) override {}
238 | 
239 |  private:
240 |   // Set only when `this` was created on the main thread, or cloned from a
241 |   // provider which was created on the main thread.
242 |   scoped_refptr<base::SequencedTaskRunner> main_thread_task_runner_;
243 | };
