264 | void ShellContentRendererClient::SetUpWebAssemblyTrapHandler() {
265 | #if BUILDFLAG(IS_WIN) || BUILDFLAG(IS_MAC)
266 |   // Mac and Windows use the default implementation (where the default v8 trap
267 |   // handler gets set up).
268 |   ContentRendererClient::SetUpWebAssemblyTrapHandler();
269 |   return;
270 | #else
271 |   base::CommandLine* const command_line =
272 |       base::CommandLine::ForCurrentProcess();
273 |   const bool crash_reporter_enabled =
274 |       command_line->HasSwitch(switches::kEnableCrashReporter)
275 | #if BUILDFLAG(IS_POSIX)
276 |       || command_line->HasSwitch(switches::kEnableCrashReporterForTesting)
277 | #endif  // BUILDFLAG(IS_POSIX)
278 |       ;
279 | 
280 |   if (crash_reporter_enabled) {
281 |     // If either --enable-crash-reporter or --enable-crash-reporter-for-testing
282 |     // is enabled it should take care of signal handling for us, use the default
283 |     // implementation which doesn't register an additional handler.
284 |     ContentRendererClient::SetUpWebAssemblyTrapHandler();
285 |     return;
286 |   }
287 | 
288 |   const bool use_v8_default_handler =
289 | #if defined(ENABLE_WEB_ASSEMBLY_TRAP_HANDLER_LINUX)
290 |       base::CommandLine::ForCurrentProcess()->HasSwitch(
291 |           switches::kDisableInProcessStackTraces)
292 | #else
293 |       true
294 | #endif  // defined(ENABLE_WEB_ASSEMBLY_TRAP_HANDLER_LINUX)
295 |       ;
296 | 
297 |   if (use_v8_default_handler) {
298 |     // There is no signal handler yet, but it's okay if v8 registers one.
299 |     v8::V8::EnableWebAssemblyTrapHandler(/*use_v8_signal_handler=*/true);
300 |     return;
301 |   }
302 | 
303 | #if defined(ENABLE_WEB_ASSEMBLY_TRAP_HANDLER_LINUX)
304 |   if (base::debug::SetStackDumpFirstChanceCallback(
305 |           v8::TryHandleWebAssemblyTrapPosix)) {
306 |     // Crashpad and Breakpad are disabled, but the in-process stack dump
307 |     // handlers are enabled, so set the callback on the stack dump handlers.
308 |     v8::V8::EnableWebAssemblyTrapHandler(/*use_v8_signal_handler=*/false);
309 |     return;
310 |   }
311 | 
312 |   // As the registration of the callback failed, we don't enable trap
313 |   // handlers.
314 | #endif  // defined(ENABLE_WEB_ASSEMBLY_TRAP_HANDLER_LINUX)
315 | #endif  // BUILDFLAG(IS_WIN) || BUILDFLAG(IS_MAC)
316 | }
