349 | bool ShellContentRendererClient::OverrideCreatePlugin(
350 |     RenderFrame* render_frame,
351 |     const blink::WebPluginParams& params,
352 |     blink::WebPlugin** plugin) {
353 |   // Tries to create a SurfaceEmbedWebPlugin for
354 |   // <embed type="application/x-chromium-surface-embed">. The renderer process
355 |   // will render an indication of error (a "sad webpage") in the plugin area if
356 |   // the browser process does not provide the SurfaceEmbedHost interface.
357 |   // Many embedders will choose to kill the renderer in that case, however.
358 |   //
359 |   // The interface is available in surface embed's content_browsertests /
360 |   // components_browsertests by overriding
361 |   // RegisterBrowserInterfaceBindersForFrame and is not available in the general
362 |   // content_shell. content_shell's default browser-side implementation triggers
363 |   // the fallback behavior, not a renderer crash.
364 |   if (surface_embed::MaybeCreatePlugin(render_frame, params, plugin)) {
365 |     return true;
366 |   }
367 | 
368 |   return false;
369 | }
